def word_count_ascii(text):
    words = []
    current = []
    for ch in text:
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z'):
            if 'A' <= ch <= 'Z':
                current.append(chr(ord(ch) + 32))
