def word_count_ascii(text: str) -> list[list[str, int]]:
    result = []
    current = []
    for ch in text:
        code = ord(ch)
        is_letter = 65 <= code <= 90 or 97 <= code <= 122
        if is_letter:
            if 65 <= code <= 90:
                current.append(chr(code + 32))
            else:
                current.append(ch)
        else:
            if current:
                word = ''.join(current)
                result.append([word, result.count(word) + 1] if word not in [r[0] for r in result] else [word, next(r[1] for r in result if r[0] == word) + 1])
                current = []
    if current:
        word = ''.join(current)
        result.append([word, result.count(word) + 1] if word not in [r[0] for r in result] else [word, next(r[1] for r in result if r[0] == word) + 1])
    result.sort(key=lambda x: x[0])
    return result
